INSERT INTO document_types (id, tenant_id, establishment_id, code, label, category, type_letter, number_template, qr_enabled, blockable, variables, signer_role, created_at, updated_at) VALUES ('01SECDT2100000000000000000', '*', '', 'sec_doc21_internship_agreement', 'Convention de stage (DOC-21)', 'other', 'S', '{CODE}-{AA}-{LETTRE}-{N6}', 1, 0, '["academic_year","class_name","company_name","company_address","tutor_name","starts_on","ends_on","activities_block"]', 'sec_chef_etablissement', '2026-11-07T03:02:00+01:00', '2026-11-07T03:02:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01SECDT21F0000000000000000', '*', '', 'sec_doc21_internship_agreement', 'fr', '<html><body><style>pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:9px}</style><h1>{{establishment_name}}</h1><h2>Convention de stage</h2><p>Année scolaire : {{academic_year}}</p><p>Stagiaire : <strong>{{holder_name}}</strong>, classe {{class_name}}</p><p>Entreprise d’accueil : {{company_name}}, {{company_address}}</p><p>Tuteur en entreprise : {{tutor_name}}</p><p>Période : du {{starts_on}} au {{ends_on}}</p><p>Activités prévues :</p><pre>{{activities_block}}</pre><p>Les clauses de la convention sont celles que l’établissement a validées dans ce modèle.</p><p>Signatures : l’élève, le parent ou tuteur, l’entreprise d’accueil, le chef d’établissement.</p><p>Fait le {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><div>{{qr}}</div><p>Numéro : {{number}}</p></body></html>', 1, '2026-11-07T03:02:00+01:00', NULL, '2026-11-07T03:02:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01SECDT21E0000000000000000', '*', '', 'sec_doc21_internship_agreement', 'en', '<html><body><style>pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:9px}</style><h1>{{establishment_name}}</h1><h2>Internship agreement</h2><p>School year: {{academic_year}}</p><p>Trainee: <strong>{{holder_name}}</strong>, class {{class_name}}</p><p>Host company: {{company_name}}, {{company_address}}</p><p>Company tutor: {{tutor_name}}</p><p>Period: from {{starts_on}} to {{ends_on}}</p><p>Planned activities:</p><pre>{{activities_block}}</pre><p>The terms of this agreement are those the school has approved in this template.</p><p>Signatures: the student, the parent or guardian, the host company, the head of school.</p><p>Issued on {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><div>{{qr}}</div><p>Number: {{number}}</p></body></html>', 1, '2026-11-07T03:02:00+01:00', NULL, '2026-11-07T03:02:00+01:00');
INSERT INTO document_types (id, tenant_id, establishment_id, code, label, category, type_letter, number_template, qr_enabled, blockable, variables, signer_role, created_at, updated_at) VALUES ('01SECDT2200000000000000000', '*', '', 'sec_doc22_trainee_appraisal', 'Fiche d’appréciation du stagiaire (DOC-22)', 'other', 'V', '{CODE}-{AA}-{LETTRE}-{N6}', 0, 0, '["academic_year","class_name","company_name","tutor_name","starts_on","ends_on","appraisal_block"]', NULL, '2026-11-07T03:02:00+01:00', '2026-11-07T03:02:00+01:00');
