INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01SECDT22E0000000000000000', '*', '', 'sec_doc22_trainee_appraisal', 'en', '<html><body><style>pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:9px}</style><h1>{{establishment_name}}</h1><h2>Trainee appraisal form</h2><p>School year: {{academic_year}}</p><p>Trainee: <strong>{{holder_name}}</strong>, class {{class_name}}</p><p>Host company: {{company_name}}</p><p>Company tutor: {{tutor_name}}</p><p>Period: from {{starts_on}} to {{ends_on}}</p><p>Tutor appraisal:</p><pre>{{appraisal_block}}</pre><p>Signature of the company tutor</p><p>Issued on {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Number: {{number}}</p></body></html>', 1, '2026-11-07T03:02:00+01:00', NULL, '2026-11-07T03:02:00+01:00');
INSERT INTO document_types (id, tenant_id, establishment_id, code, label, category, type_letter, number_template, qr_enabled, blockable, variables, signer_role, created_at, updated_at) VALUES ('01SECDT2300000000000000000', '*', '', 'sec_doc23_workshop_sheet', 'Fiche de travaux pratiques et grille d’évaluation (DOC-23)', 'other', 'T', '{CODE}-{AA}-{LETTRE}-{N6}', 0, 0, '["academic_year","class_name","workshop_name","sheet_title","objectives_block","materials_block","safety_block","criteria_block"]', NULL, '2026-11-07T03:02:00+01:00', '2026-11-07T03:02:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01SECDT23F0000000000000000', '*', '', 'sec_doc23_workshop_sheet', 'fr', '<html><body><style>pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:9px}</style><h1>{{establishment_name}}</h1><h2>Fiche de travaux pratiques</h2><p>Année scolaire : {{academic_year}} · Classe : {{class_name}} · Atelier : {{workshop_name}}</p><p>Élève : <strong>{{holder_name}}</strong></p><h3>{{sheet_title}}</h3><p>Objectifs :</p><pre>{{objectives_block}}</pre><p>Matière d’œuvre et outillage :</p><pre>{{materials_block}}</pre><p>Consignes de sécurité et protections :</p><pre>{{safety_block}}</pre><p>Grille d’évaluation :</p><pre>{{criteria_block}}</pre><p>Professeur d’atelier</p><p>Fait le {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Numéro : {{number}}</p></body></html>', 1, '2026-11-07T03:02:00+01:00', NULL, '2026-11-07T03:02:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01SECDT23E0000000000000000', '*', '', 'sec_doc23_workshop_sheet', 'en', '<html><body><style>pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:9px}</style><h1>{{establishment_name}}</h1><h2>Workshop practical sheet</h2><p>School year: {{academic_year}} · Class: {{class_name}} · Workshop: {{workshop_name}}</p><p>Student: <strong>{{holder_name}}</strong></p><h3>{{sheet_title}}</h3><p>Objectives:</p><pre>{{objectives_block}}</pre><p>Materials and tools:</p><pre>{{materials_block}}</pre><p>Safety rules and protective equipment:</p><pre>{{safety_block}}</pre><p>Assessment grid:</p><pre>{{criteria_block}}</pre><p>Workshop teacher</p><p>Issued on {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Number: {{number}}</p></body></html>', 1, '2026-11-07T03:02:00+01:00', NULL, '2026-11-07T03:02:00+01:00');
INSERT INTO document_types (id, tenant_id, establishment_id, code, label, category, type_letter, number_template, qr_enabled, blockable, variables, signer_role, created_at, updated_at) VALUES ('01SECDT2400000000000000000', '*', '', 'sec_doc24_material_stock', 'État du stock de matière d’œuvre (DOC-24)', 'other', 'M', '{CODE}-{AA}-{LETTRE}-{N6}', 0, 0, '["academic_year","workshop_name","as_of","stock_block","cost_per_student"]', NULL, '2026-11-07T03:02:00+01:00', '2026-11-07T03:02:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01SECDT24F0000000000000000', '*', '', 'sec_doc24_material_stock', 'fr', '<html><body><style>pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:9px}</style><h1>{{establishment_name}}</h1><h2>État du stock de matière d’œuvre</h2><p>Année scolaire : {{academic_year}} · Atelier : {{workshop_name}}</p><p>Situation au {{as_of}}, établie par {{holder_name}}</p><pre>{{stock_block}}</pre><p>Coût de la matière d’œuvre par élève : {{cost_per_student}}</p><p>Chef des travaux</p><p>Fait le {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Numéro : {{number}}</p></body></html>', 1, '2026-11-07T03:02:00+01:00', NULL, '2026-11-07T03:02:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01SECDT24E0000000000000000', '*', '', 'sec_doc24_material_stock', 'en', '<html><body><style>pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:9px}</style><h1>{{establishment_name}}</h1><h2>Workshop materials stock report</h2><p>School year: {{academic_year}} · Workshop: {{workshop_name}}</p><p>Situation as of {{as_of}}, drawn up by {{holder_name}}</p><pre>{{stock_block}}</pre><p>Materials cost per student: {{cost_per_student}}</p><p>Head of workshops</p><p>Issued on {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Number: {{number}}</p></body></html>', 1, '2026-11-07T03:02:00+01:00', NULL, '2026-11-07T03:02:00+01:00');
INSERT INTO document_types (id, tenant_id, establishment_id, code, label, category, type_letter, number_template, qr_enabled, blockable, variables, signer_role, created_at, updated_at) VALUES ('01SECDT3000000000000000000', '*', '', 'sec_doc30_payroll_payslip', 'État des vacations et bulletin de paie (DOC-30)', 'other', 'W', '{CODE}-{AA}-{LETTRE}-{N6}', 0, 0, '["period_month","payroll_ref","gross_amount","deductions_block","deductions_amount","net_amount"]', 'sec_chef_etablissement', '2026-11-07T03:02:00+01:00', '2026-11-07T03:02:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01SECDT30F0000000000000000', '*', '', 'sec_doc30_payroll_payslip', 'fr', '<html><body><style>pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:9px}</style><h1>{{establishment_name}}</h1><h2>Bulletin de paie</h2><p>Membre du personnel : <strong>{{holder_name}}</strong> · Référence de paie : {{payroll_ref}}</p><p>Mois : {{period_month}}</p><p>Brut : {{gross_amount}}</p><p>Retenues :</p><pre>{{deductions_block}}</pre><p>Total des retenues : {{deductions_amount}}</p><p><strong>Net à payer : {{net_amount}}</strong></p><p>Montants saisis par l’établissement, sans calcul de cotisation légale.</p><p>Fait le {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Numéro : {{number}}</p></body></html>', 1, '2026-11-07T03:02:00+01:00', NULL, '2026-11-07T03:02:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01SECDT30E0000000000000000', '*', '', 'sec_doc30_payroll_payslip', 'en', '<html><body><style>pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:9px}</style><h1>{{establishment_name}}</h1><h2>Payslip</h2><p>Staff member: <strong>{{holder_name}}</strong> · Payroll reference: {{payroll_ref}}</p><p>Month: {{period_month}}</p><p>Gross: {{gross_amount}}</p><p>Deductions:</p><pre>{{deductions_block}}</pre><p>Total deductions: {{deductions_amount}}</p><p><strong>Net pay: {{net_amount}}</strong></p><p>Amounts entered by the school, no statutory contribution is computed.</p><p>Issued on {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Number: {{number}}</p></body></html>', 1, '2026-11-07T03:02:00+01:00', NULL, '2026-11-07T03:02:00+01:00');
